{"qas": [
  {"question": "According to the AGILE Index 2025, which two countries together account for over 70% of impactful open AI models and datasets, and what is their combined share of AI governance publications?", "answer": "China and the United States together account for over 70% of impactful open AI models and datasets, and about 54% of AI governance publications.", "evidence": [{"page": 37, "quote": "China and the United States represent the highest shares in the openness of impactful AI models and datasets, together account for more than 70% of the total observed among all 40 countries."}, {"page": 39, "quote": "Among the 40 countries, China and the US together account for about 54% of contributions, over half."}]},
  {"question": "In the AGILE Index 2025, which Sustainable Development Goals receive the most AI research attention, and how does this differ between high-income and upper-middle/lower-middle income countries?", "answer": "SDG 3, SDG 11, and SDG 9 receive the most attention. High-income countries focus more on social-level SDGs, while upper-middle/lower-middle income countries focus more on economic and environmental SDGs.", "evidence": [{"page": 43, "quote": "SDG3 (Good Health and Well-Being), SDG11 (Sustainable Cities and Communities), and SDG9 (Industry, Innovation and Infrastructure) have received widespread research attention. Meanwhile, High-Income Countries have allocated higher AI research attention to social-level SDGs, while Upper-Middle&Lower-Middle Income Countries have relatively higher AI research attention to economically and environmentally related SDGs."}, {"page": 44, "quote": "the high-income country group has relatively higher attention to goals such as SDG 3 (Good Health and Well-being), SDG 5 (Gender Equality), and SDG 16 (Peace, Justice and Strong Institutions) than the upper-middle&lower-middle income country group. In contrast, the latter have relatively higher research attention to goals including SDG 6 (Clean Water and Sanitation), SDG 7 (Affordable and Clean Energy), SDG 9 (Industry, Innovation and Infrastructure), and SDG 11 (Sustainable Cities and Communities)."}]},
  {"question": "What is the definition of 'AI Research and Development Activity' in the AGILE Index 2025, and which UNESCO Recommendation article supports it?", "answer": "'AI Research and Development Activity' refers to the level of activity in AI-related research and development in various countries, supported by UNESCO Article 83.", "evidence": [{"page": 63, "quote": "AI Research and Development Activity refers to the level of activity in artificial intelligence-related research and development in various countries. According to UNESCO's Recommendation on the Ethics of Artificial Intelligence, Article 83, \"Member States should encourage international cooperation and collaboration in the field of AI to bridge geo-technological lines.\""}]},
  {"question": "Which indicator in the AGILE Index 2025 measures the share of young females who can program, and under which pillar and dimension does it fall?", "answer": "The indicator is D15.3. Share of young females who can program, under Pillar P4. AI Governance Effectiveness, Dimension D15. AI Development Inclusivity.", "evidence": [{"page": 62, "quote": "D15.3. Share of young females who can program"}]},
  {"question": "Which country has the most balanced male-to-female author ratio in AI research according to the AGILE Index 2025, and how is gender information inferred?", "answer": "Thailand has the most balanced male-to-female author ratio; gender information is inferred from author names in DBLP using country-specific naming conventions.", "evidence": [{"page": 35, "quote": "In the 40 countries evaluated, Thailand has the most balanced male-to-female author ratio, followed by China, Indonesia, and Singapore; countries in North America and Western Europe do not hold a distinct advantage. ... Gender information is inferred from author names in DBLP based on country-specific naming conventions."}]},
  {"question": "How does the AGILE Index 2025 describe the trend in the male-to-female ratio among AI researchers from 2017 to 2025?", "answer": "The male-to-female author ratio dropped from 4.0:1 in 2017 to 2.2:1 in 2025, indicating growing female participation.", "evidence": [{"page": 35, "quote": "The male-to-female author ratio dropped from 4.0:1 in 2017 to 2.2:1 in 2025, reflecting the growing participation of women in AI-related scientific research."}]}
]}
